 private void load(JSONObject record)throws Exception{baseline=RiskSettingsModel.validateRecord(record);filling=true;try{for(String key:fields.keySet())fields.get(key).setText(Double.toString(record.getJSONObject("thresholds").getDouble(key)));}finally{filling=false;}dirty=false;}
